gql(){return"\u062a\u0645 \u0625\u0631\u0633\u0627\u0644 \u0627\u0644\u0628\u0644\u0627\u063a \u0628\u0646\u062c\u0627\u062d"},
gnR(){return"\u062a\u062d\u062a \u0627\u0644\u0635\u064a\u0627\u0646\u0629"},
gnQ(){return"Cortex \u063a\u064a\u0631 \u0645\u062a\u0635\u0644 \u0645\u0624\u0642\u062a\u064b\u0627 \u0628\u064a\u0646\u0645\u0627 \u0646\u0642\u0648\u0645 \u0628\u0637\u0631\u062d \u0628\u0639\u0636 \u0627\u0644\u062a\u062d\u062f\u064a\u062b\u0627\u062a \u0627\u0644\u0645\u0647\u0645\u0629. \u0633\u064a\u062a\u0645 \u0627\u0633\u062a\u0639\u0627\u062f\u0629 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0642\u0631\u064a\u0628\u064b\u0627.\n\n\u0634\u0643\u0631\u064b\u0627 \u0644\u0643 \u0639\u0644\u0649 \u0633\u0639\u0629 \u0635\u062f\u0631\u0643 \u0628\u064a\u0646\u0645\u0627 \u0646\u0642\u0648\u0645 \u0628\u062a\u062d\u0633\u064a\u0646 \u062a\u062c\u0631\u0628\u062a\u0643."},
gjn(){return"\u062a\u0645 \u0627\u0643\u062a\u0634\u0627\u0641 \u0631\u0633\u0627\u0644\u062a\u0643 \u0639\u0644\u0649 \u0623\u0646\u0647\u0627 \u063a\u064a\u0631 \u0644\u0627\u0626\u0642\u0629 \u0648\u0644\u0645 \u064a\u062a\u0645 \u0625\u0631\u0633\u0627\u0644\u0647\u0627."},
gmV(){return"\u0644\u0642\u062f \u0623\u0646\u0634\u0623\u062a \u0639\u062f\u062f\u064b\u0627 \u0643\u0628\u064a\u0631\u064b\u0627 \u062c\u062f\u064b\u0627 \u0645\u0646 \u0627\u0644\u0646\u0645\u0627\u0630\u062c \u0645\u0624\u062e\u0631\u064b\u0627\u060c \u064a\u0631\u062c\u0649 \u0627\u0644\u0627\u0646\u062a\u0638\u0627\u0631 \u0628\u0639\u0636 \u0627\u0644\u0648\u0642\u062a \u0642\u0628\u0644 \u0627\u0644\u0645\u062d\u0627\u0648\u0644\u0629 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649."},
gmQ(){return"\u062a\u0639\u0630\u0631 \u062d\u0641\u0638 \u0627\u0644\u0646\u0645\u0648\u0630\u062c \u0644\u0623\u0646 \u0645\u062d\u062a\u0648\u0627\u0647 \u062a\u0645 \u0627\u0644\u0625\u0628\u0644\u0627\u063a \u0639\u0646\u0647 \u0639\u0644\u0649 \u0623\u0646\u0647 \u063a\u064a\u0631 \u0644\u0627\u0626\u0642."},
