gr0(){return"\u092f\u0939 \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e \u0916\u093e\u0924\u093e \u0905\u0915\u094d\u0937\u092e \u0915\u0930 \u0926\u093f\u092f\u093e \u0917\u092f\u093e \u0939\u0948\u0964"},
gnN(){return"\u0905\u092a\u0928\u0947 \u0935\u0930\u094d\u091f\u0947\u0915\u094d\u0938 \u0916\u093e\u0924\u0947 \u092e\u0947\u0902 \u0932\u0949\u0917 \u0907\u0928 \u0915\u0930\u0947\u0902\u0964 \u091c\u093e\u0930\u0940 \u0930\u0916\u0915\u0930, \u0906\u092a \u0939\u092e\u093e\u0930\u0940 \u0938\u0947\u0935\u093e \u0915\u0940 \u0936\u0930\u094d\u0924\u094b\u0902 \u0914\u0930 \u0917\u094b\u092a\u0928\u0940\u092f\u0924\u093e \u0928\u0940\u0924\u093f \u0938\u0947 \u0938\u0939\u092e\u0924 \u0939\u094b\u0924\u0947 \u0939\u0948\u0902\u0964"},
gq9(){return"\u0939\u092e\u093e\u0930\u0940 \u0938\u092d\u0940 \u0938\u0947\u0935\u093e\u0913\u0902 \u0924\u0915 \u0928\u093f\u0930\u094d\u092c\u093e\u0927 \u092a\u0939\u0941\u0901\u091a \u0915\u0947 \u0932\u093f\u090f \u090f\u0915 \u0935\u0930\u094d\u091f\u0947\u0915\u094d\u0938 \u0916\u093e\u0924\u093e \u092c\u0928\u093e\u090f\u0901\u0964 \u091c\u093e\u0930\u0940 \u0930\u0916\u0915\u0930, \u0906\u092a \u0939\u092e\u093e\u0930\u0940 \u0938\u0947\u0935\u093e \u0915\u0940 \u0936\u0930\u094d\u0924\u094b\u0902 \u0914\u0930 \u0917\u094b\u092a\u0928\u0940\u092f\u0924\u093e \u0928\u0940\u0924\u093f \u0938\u0947 \u0938\u0939\u092e\u0924 \u0939\u094b\u0924\u0947 \u0939\u0948\u0902\u0964"},
