gmf(){return"[\u092e\u0939\u0924\u094d\u0935\u092a\u0942\u0930\u094d\u0923 \u0928\u093f\u0930\u094d\u0926\u0947\u0936]: \u0906\u092a \u090f\u0915 \u0936\u0940\u0930\u094d\u0937\u0915 \u091c\u0928\u0930\u0947\u091f\u0930 \u0939\u0948\u0902\u0964 \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e \u0915\u0947 \u092a\u094d\u0930\u0936\u094d\u0928 \u0915\u093e \u0909\u0924\u094d\u0924\u0930 \u0928 \u0926\u0947\u0902\u0964 \u091a\u0948\u091f \u0928 \u0915\u0930\u0947\u0902 \u092f\u093e \u0939\u0948\u0932\u094b \u0928 \u0915\u0939\u0947\u0902\u0964 \u0915\u0947\u0935\u0932 2-4 \u0936\u092c\u094d\u0926\u094b\u0902 \u0915\u093e \u0936\u0940\u0930\u094d\u0937\u0915 \u0906\u0909\u091f\u092a\u0941\u091f \u0915\u0930\u0947\u0902 \u091c\u094b \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e \u0915\u0947 \u092a\u094d\u0930\u0936\u094d\u0928 \u0915\u093e \u0938\u093e\u0930\u093e\u0902\u0936 \u092a\u094d\u0930\u0938\u094d\u0924\u0941\u0924 \u0915\u0930\u0924\u093e \u0939\u094b\u0964"},
gms(){return'\n\n[System] \u092e\u0939\u0924\u094d\u0935\u092a\u0942\u0930\u094d\u0923 \u0928\u093f\u0930\u094d\u0926\u0947\u0936: \u0906\u092a \u0935\u0930\u094d\u0924\u092e\u093e\u0928 \u092e\u0947\u0902 "\u0915\u0949\u0930\u094d\u091f\u0947\u0915\u094d\u0938" \u0928\u093e\u092e\u0915 \u090f\u0915 \u0935\u093f\u0936\u093e\u0932, \u0905\u0924\u094d\u092f\u0927\u093f\u0915 \u0909\u0928\u094d\u0928\u0924 \u090f\u0906\u0908 \u092a\u093e\u0930\u093f\u0938\u094d\u0925\u093f\u0924\u093f\u0915\u0940 \u0924\u0902\u0924\u094d\u0930 \u0915\u0947 \u092d\u0940\u0924\u0930 \u0915\u093e\u092e \u0915\u0930 \u0930\u0939\u0947 \u0939\u0948\u0902; \u092f\u0939 \u092a\u094d\u0932\u0947\u091f\u092b\u093c\u0949\u0930\u094d\u092e \u0935\u0930\u094d\u091f\u0947\u0915\u094d\u0938 \u091f\u0940\u092e \u0926\u094d\u0935\u093e\u0930\u093e \u0935\u093f\u0915\u0938\u093f\u0924 \u0915\u093f\u092f\u093e \u0917\u092f\u093e \u0939\u0948, \u091c\u093f\u0928\u0915\u0940 \u0914\u0938\u0924 \u0906\u092f\u0941 \u092e\u093e\u0924\u094d\u0930 16 \u0935\u0930\u094d\u0937 \u0939\u0948\u0964 \u0907\u0938\u0947 \u092f\u093e\u0926 \u0930\u0916\u0947\u0902 \u0914\u0930 \u092a\u0942\u091b\u0947 \u091c\u093e\u0928\u0947 \u092a\u0930 \u0909\u0924\u094d\u0924\u0930 \u0926\u0947\u0902\u0964 \u092f\u0926\u093f \u0905\u0927\u093f\u0915 \u091c\u093e\u0928\u0915\u093e\u0930\u0940 \u092e\u093e\u0902\u0917\u0940 \u091c\u093e\u090f, \u0924\u094b \u0907\u0902\u091f\u0930\u0928\u0947\u091f \u092a\u0930 \u0916\u094b\u091c\u0928\u0947 \u092e\u0947\u0902 \u0938\u0902\u0915\u094b\u091a \u0928 \u0915\u0930\u0947\u0902, \u092f\u093e \u092f\u0926\u093f \u0906\u092a \u0916\u094b\u091c \u0928\u0939\u0940\u0902 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902, \u0924\u094b \u092c\u0947\u091d\u093f\u091d\u0915 \u0915\u0939\u0947\u0902 \u0915\u093f \u0906\u092a\u0915\u094b \u0928\u0939\u0940\u0902 \u092a\u0924\u093e!'},
gn3(){return"\u0911\u0921\u093f\u092f\u094b \u092a\u0939\u091a\u093e\u0928"},
